1	package incidents
2	
3	import (
4		"errors"
5		"strconv"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// fakeEvents is an in-memory EventLookup.
12	type fakeEvents struct {
13		services map[string]string
14	}
15	
16	func (f *fakeEvents) LookupEvent(id string) (string, bool) {
17		service, ok := f.services[id]
18		return service, ok
19	}
20	
21	// fakeCommit counts durable writes and can be made to fail.
22	type fakeCommit struct {
23		mu       sync.Mutex
24		records  []Record
25		failOnce bool
26		failed   bool
27	}
28	
29	func (c *fakeCommit) commit(record Record) error {
30		c.mu.Lock()
31		defer c.mu.Unlock()
32		if c.failOnce && !c.failed {
33			c.failed = true
34			return errors.New("disk full")
35		}
36		c.records = append(c.records, record)
37		return nil
38	}
39	
40	func (c *fakeCommit) count() int {
41		c.mu.Lock()
42		defer c.mu.Unlock()
43		return len(c.records)
44	}
45	
46	func newTestRegistry(events EventLookup) (*Registry, *fakeCommit, *tickingClock) {
47		commit := &fakeCommit{}
48		clock := newTickingClock()
49		reg := NewRegistry(events, commit.commit, WithClock(clock.now))
50		return reg, commit, clock
51	}
52	
53	// tickingClock hands out strictly increasing instants even when the wall
54	// clock would not, which also models monotonic wall time across commits.
55	type tickingClock struct {
56		mu sync.Mutex
57		t  time.Time
58	}
59	
60	func newTickingClock() *tickingClock {
61		return &tickingClock{t: time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)}
62	}
63	
64	func (c *tickingClock) now() time.Time {
65		c.mu.Lock()
66		defer c.mu.Unlock()
67		c.t = c.t.Add(time.Nanosecond)
68		return c.t
69	}
70	
71	func validCreation() Creation {
72		return Creation{ID: "INC-1", Title: " Outage ", Service: "gateway", Operator: " Alice "}
73	}
74	
75	func TestCreateNormalizesReplaysAndConflicts(t *testing.T) {
76		reg, commit, _ := newTestRegistry(&fakeEvents{})
77	
78		res, err := reg.Create(validCreation())
79		if err != nil {
80			t.Fatalf("create: %v", err)
81		}
82		if res != (CreateResult{ID: "INC-1", Status: StatusOpen, Version: 1}) {
83			t.Fatalf("unexpected create result %+v", res)
84		}
85	
86		got, err := reg.Get("INC-1")
87		if err != nil {
88			t.Fatal(err)
89		}
90		if got.Title != "Outage" || got.Service != "gateway" {
91			t.Fatalf("whitespace must be trimmed: %+v", got)
92		}
93		if got.History[0].Operator != "Alice" {
94			t.Fatalf("operator case/space: %+v", got.History[0])
95		}
96	
97		// Identical creation after trimming replays the first result.
98		replay, err := reg.Create(Creation{ID: "INC-1", Title: "Outage", Service: "gateway", Operator: "Alice"})
99		if err != nil {
100			t.Fatalf("replay: %v", err)
101		}
102		if replay != res {
103			t.Fatalf("replay must return first result %+v, got %+v", res, replay)
104		}
105		if commit.count() != 1 {
106			t.Fatalf("replay must not persist again, count=%d", commit.count())
107		}
108	
109		// Different content for the same id conflicts.
110		_, err = reg.Create(Creation{ID: "INC-1", Title: "Changed", Service: "gateway", Operator: "Alice"})
111		if !IsConflictError(err) {
112			t.Fatalf("want conflict, got %v", err)
113		}
114		if commit.count() != 1 {
115			t.Fatal("conflict must not persist")
116		}
117	}
118	
119	func TestCreateValidation(t *testing.T) {
120		reg, _, _ := newTestRegistry(&fakeEvents{})
121		for field, mutate := range map[string]func(Creation) Creation{
122			"id":       func(c Creation) Creation { c.ID = "  "; return c },
123			"title":    func(c Creation) Creation { c.Title = ""; return c },
124			"service":  func(c Creation) Creation { c.Service = "\t"; return c },
125			"operator": func(c Creation) Creation { c.Operator = ""; return c },
126		} {
127			if _, err := reg.Create(mutate(validCreation())); !IsValidationError(err) {
128				t.Fatalf("field %s: want validation error, got %v", field, err)
129			}
130		}
131	}
132	
133	func TestCreateKeepsInteriorCase(t *testing.T) {
134		reg, _, _ := newTestRegistry(&fakeEvents{})
135		in := validCreation()
136		in.Title = "Payments API Down"
137		if _, err := reg.Create(in); err != nil {
138			t.Fatal(err)
139		}
140		got, _ := reg.Get("INC-1")
141		if got.Title != "Payments API Down" {
142			t.Fatalf("interior case changed: %q", got.Title)
143		}
144	}
145	
146	func TestActionLifecycle(t *testing.T) {
147		lookup := &fakeEvents{services: map[string]string{"e1": "gateway", "e2": "checkout"}}
148		reg, commit, _ := newTestRegistry(lookup)
149		if _, err := reg.Create(validCreation()); err != nil {
150			t.Fatal(err)
151		}
152	
153		note := Request{IncidentID: "INC-1", ActionID: "n1", Operator: "bob", ExpectedVersion: 1, Type: ActionNote, Content: " looking "}
154		res, err := reg.Apply(note)
155		if err != nil {
156			t.Fatalf("note: %v", err)
157		}
158		if res != (ActionResult{IncidentID: "INC-1", ActionID: "n1", Version: 2}) {
159			t.Fatalf("note result %+v", res)
160		}
161	
162		// Link a same-service event.
163		link := Request{IncidentID: "INC-1", ActionID: "l1", Operator: "bob", ExpectedVersion: 2, Type: ActionLinkEvent, Content: "e1"}
164		res, err = reg.Apply(link)
165		if err != nil {
166			t.Fatalf("link: %v", err)
167		}
168		if res.Version != 3 {
169			t.Fatalf("link version %d", res.Version)
170		}
171	
172		inc, _ := reg.Get("INC-1")
173		if len(inc.Links) != 1 || inc.Links[0] != "e1" {
174			t.Fatalf("links %+v", inc.Links)
175		}
176		if commit.count() != 3 { // create + note + link
177			t.Fatalf("commit count %d", commit.count())
178		}
179	
180		// Unknown event -> not found.
181		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "l2", Operator: "bob", ExpectedVersion: 3, Type: ActionLinkEvent, Content: "missing"})
182		if !IsNotFoundError(err) {
183			t.Fatalf("missing event: want not-found, got %v", err)
184		}
185	
186		// Different service -> conflict.
187		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "l3", Operator: "bob", ExpectedVersion: 3, Type: ActionLinkEvent, Content: "e2"})
188		if !IsConflictError(err) {
189			t.Fatalf("wrong service: want conflict, got %v", err)
190		}
191	
192		// Already linked -> conflict.
193		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "l4", Operator: "bob", ExpectedVersion: 3, Type: ActionLinkEvent, Content: "e1"})
194		if !IsConflictError(err) {
195			t.Fatalf("dup link: want conflict, got %v", err)
196		}
197	
198		// Resolve, after which only reopen is allowed.
199		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "r1", Operator: "bob", ExpectedVersion: 3, Type: ActionResolve, Content: "fixed"})
200		if err != nil {
201			t.Fatalf("resolve: %v", err)
202		}
203		inc, _ = reg.Get("INC-1")
204		if inc.Status != StatusResolved || inc.Version != 4 {
205			t.Fatalf("post-resolve state %+v", inc)
206		}
207		for _, bad := range []Request{
208			{IncidentID: "INC-1", ActionID: "x1", Operator: "b", ExpectedVersion: 4, Type: ActionNote, Content: "c"},
209			{IncidentID: "INC-1", ActionID: "x2", Operator: "b", ExpectedVersion: 4, Type: ActionLinkEvent, Content: "e1"},
210			{IncidentID: "INC-1", ActionID: "x3", Operator: "b", ExpectedVersion: 4, Type: ActionResolve, Content: "again"},
211		} {
212			if _, err := reg.Apply(bad); !IsConflictError(err) {
213				t.Fatalf("resolved+%s: want conflict, got %v", bad.Type, err)
214			}
215		}
216	
217		// Reopen, then a note works again.
218		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "o1", Operator: "bob", ExpectedVersion: 4, Type: ActionReopen, Content: "regression"})
219		if err != nil {
220			t.Fatalf("reopen: %v", err)
221		}
222		inc, _ = reg.Get("INC-1")
223		if inc.Status != StatusOpen || inc.Version != 5 {
224			t.Fatalf("post-reopen state %+v", inc)
225		}
226	}
227	
228	func TestActionVersionConflictReportsCurrent(t *testing.T) {
229		lookup := &fakeEvents{services: map[string]string{"e1": "gateway"}}
230		reg, _, _ := newTestRegistry(lookup)
231		_, _ = reg.Create(validCreation())
232		_, _ = reg.Apply(Request{IncidentID: "INC-1", ActionID: "n1", Operator: "b", ExpectedVersion: 1, Type: ActionNote, Content: "c"})
233	
234		_, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "n2", Operator: "b", ExpectedVersion: 1, Type: ActionNote, Content: "c"})
235		var conflict *ConflictError
236		if !errors.As(err, &conflict) {
237			t.Fatalf("want conflict, got %v", err)
238		}
239		if conflict.CurrentVersion != 2 {
240			t.Fatalf("current version reported as %d", conflict.CurrentVersion)
241		}
242	}
243	
244	func TestActionIdempotentReplayAcrossVersions(t *testing.T) {
245		lookup := &fakeEvents{services: map[string]string{"e1": "gateway"}}
246		reg, commit, _ := newTestRegistry(lookup)
247		_, _ = reg.Create(validCreation())
248		first := Request{IncidentID: "INC-1", ActionID: "n1", Operator: "bob", ExpectedVersion: 1, Type: ActionNote, Content: "c"}
249		res, err := reg.Apply(first)
250		if err != nil {
251			t.Fatal(err)
252		}
253		// Advance the incident with a different action.
254		_, _ = reg.Apply(Request{IncidentID: "INC-1", ActionID: "l1", Operator: "bob", ExpectedVersion: 2, Type: ActionLinkEvent, Content: "e1"})
255	
256		// Replaying the first request with its now-stale expected_version still
257		// returns its first result and adds nothing.
258		replay, err := reg.Apply(first)
259		if err != nil {
260			t.Fatalf("replay across versions: %v", err)
261		}
262		if replay != res {
263			t.Fatalf("replay result %+v, want %+v", replay, res)
264		}
265		inc, _ := reg.Get("INC-1")
266		if inc.Version != 3 || len(inc.History) != 3 {
267			t.Fatalf("replay must not add a record: %+v", inc)
268		}
269		if commit.count() != 3 {
270			t.Fatalf("commit count %d", commit.count())
271		}
272	
273		// Same action id with different content conflicts.
274		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "n1", Operator: "bob", ExpectedVersion: 3, Type: ActionNote, Content: "different"})
275		if !IsConflictError(err) {
276			t.Fatalf("changed action content: want conflict, got %v", err)
277		}
278	}
279	
280	func TestActionValidation(t *testing.T) {
281		reg, _, _ := newTestRegistry(&fakeEvents{})
282		_, _ = reg.Create(validCreation())
283	
284		base := Request{IncidentID: "INC-1", ActionID: "a", Operator: "b", ExpectedVersion: 1, Type: ActionNote, Content: "c"}
285		cases := map[string]Request{
286			"empty action id":   func() Request { r := base; r.ActionID = " "; return r }(),
