287	// seededTimes returns n strictly increasing UTC instants for replay fixtures.
288	func seededTimes(n int) []time.Time {
289		times := make([]time.Time, n)
290		base := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
291		for i := range times {
292			times[i] = base.Add(time.Duration(i+1) * time.Second)
293		}
294		return times
295	}
